#include <iostream>
#include <vector>
#include <string>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long q;
    cin >> n >> q;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<vector<long long>> ops(q, vector<long long>(3));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> ops[i][j];
        }
    }

    long long size = 1;
    while (size < n) size *= 2;
    const long long LOW = -(1LL << 62);
    vector<long long> tm(2 * size, LOW), tc(2 * size, 0);
    for (long long i = 0; i < n; i++) {
        tm[size + i] = a[i];
        tc[size + i] = 1;
    }
    auto pull = [&](long long v) {
        long long l = 2 * v, rr = 2 * v + 1;
        if (tm[l] > tm[rr]) {
            tm[v] = tm[l];
            tc[v] = tc[l];
        } else if (tm[rr] > tm[l]) {
            tm[v] = tm[rr];
            tc[v] = tc[rr];
        } else {
            tm[v] = tm[l];
            tc[v] = tc[l] + tc[rr];
        }
    };
    for (long long v = size - 1; v >= 1; v--) pull(v);
    string out;
    for (long long k = 0; k < q; k++) {
        long long kind = ops[k][0], x = ops[k][1], y = ops[k][2];
        if (kind == 1) {
            long long v = size + x - 1;
            tm[v] = y;
            tc[v] = 1;
            for (v /= 2; v >= 1; v /= 2) pull(v);
        } else {
            long long lo = size + x - 1, hi = size + y, best = LOW, cnt = 0;
            auto take = [&](long long nd) {
                if (tm[nd] > best) {
                    best = tm[nd];
                    cnt = tc[nd];
                } else if (tm[nd] == best) {
                    cnt += tc[nd];
                }
            };
            while (lo < hi) {
                if (lo & 1) take(lo++);
                if (hi & 1) take(--hi);
                lo /= 2;
                hi /= 2;
            }
            if (!out.empty()) out += " ";
            out += to_string(cnt);
        }
    }
    cout << out << "\n";

    return 0;
}

