import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[][] ops = new long[(int) q][3];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = Long.parseLong(next());
            }
        }

        int size = 1;
        while (size < n) size *= 2;
        long low = -(1L << 62);
        long[] tm = new long[2 * size];
        long[] tc = new long[2 * size];
        Arrays.fill(tm, low);
        for (int i = 0; i < n; i++) {
            tm[size + i] = a[i];
            tc[size + i] = 1;
        }
        for (int v = size - 1; v >= 1; v--) {
            int l = 2 * v, rr = 2 * v + 1;
            if (tm[l] > tm[rr]) {
                tm[v] = tm[l];
                tc[v] = tc[l];
            } else if (tm[rr] > tm[l]) {
                tm[v] = tm[rr];
                tc[v] = tc[rr];
            } else {
                tm[v] = tm[l];
                tc[v] = tc[l] + tc[rr];
            }
        }
        StringBuilder out = new StringBuilder();
        for (int k = 0; k < q; k++) {
            long kind = ops[k][0];
            int x = (int) ops[k][1];
            long y = ops[k][2];
            if (kind == 1) {
                int v = size + x - 1;
                tm[v] = y;
                tc[v] = 1;
                for (v /= 2; v >= 1; v /= 2) {
                    int l = 2 * v, rr = 2 * v + 1;
                    if (tm[l] > tm[rr]) {
                        tm[v] = tm[l];
                        tc[v] = tc[l];
                    } else if (tm[rr] > tm[l]) {
                        tm[v] = tm[rr];
                        tc[v] = tc[rr];
                    } else {
                        tm[v] = tm[l];
                        tc[v] = tc[l] + tc[rr];
                    }
                }
            } else {
                int lo = size + x - 1, hi = size + (int) y;
                long best = low, cnt = 0;
                while (lo < hi) {
                    for (int side = 0; side < 2; side++) {
                        int nd = -1;
                        if (side == 0 && (lo & 1) == 1) nd = lo++;
                        else if (side == 1 && (hi & 1) == 1) nd = --hi;
                        if (nd < 0) continue;
                        if (tm[nd] > best) {
                            best = tm[nd];
                            cnt = tc[nd];
                        } else if (tm[nd] == best) {
                            cnt += tc[nd];
                        }
                    }
                    lo /= 2;
                    hi /= 2;
                }
                if (out.length() > 0) out.append(" ");
                out.append(cnt);
            }
        }
        System.out.println(out);
    }
}
